import datetime
import pprint
import re
import types
import threading

from ta_messaging.submodule_ute_common_abstract_core.aliases_registry import aliases_registry
from ta_messaging.robot_utils import _is_dry_run
from ta_messaging.message_verifiers import get_registered_verifiers
from ta_messaging.messages_subscriber import MessagesSubscriber
from ute_common_abstract_core.message_query_builder import message_query_parser

FLOW_VARIABLE_ALIAS = '__FLOW_NUMBER'
SUBSCRIBERS_ALIAS = '__SUBSCRIBERS'


def _get_flow_aliases_from_registry():
    if FLOW_VARIABLE_ALIAS not in aliases_registry():
        aliases_registry()[FLOW_VARIABLE_ALIAS] = {}
    return aliases_registry()[FLOW_VARIABLE_ALIAS]


def _get_subscribers_aliases_from_registry():
    if SUBSCRIBERS_ALIAS not in aliases_registry():
        aliases_registry()[SUBSCRIBERS_ALIAS] = {}
    return aliases_registry()[SUBSCRIBERS_ALIAS]


def _create_alias_for_data_structures(message_type, owner_alias):
    if owner_alias is not None:
        alias = "{}_{}".format(message_type, owner_alias)
    else:
        alias = message_type
    return alias


def add_flow_number_for_message_type(message_type, owner_alias=None):
    alias = _create_alias_for_data_structures(message_type, owner_alias)
    assert alias not in _get_flow_aliases_from_registry(), \
        'Subscriber for message type{}: {} already created'\
        .format(message_type, "" if owner_alias is None else "and owner: {}".format(owner_alias))
    _get_flow_aliases_from_registry()[alias] = 0


def reset_flow_number_for_message_type(message_type, owner_alias=None):
    alias = _create_alias_for_data_structures(message_type, owner_alias)
    assert alias in _get_flow_aliases_from_registry(), \
        'Subscriber for message type{}: {} already created'\
        .format(message_type, "" if owner_alias is None else "and owner: {}".format(owner_alias))
    _get_flow_aliases_from_registry()[alias] = 0


def increment_flow_number_for_message_type(message_type, owner_alias=None):
    alias = _create_alias_for_data_structures(message_type, owner_alias)
    assert alias in _get_flow_aliases_from_registry(), \
        'Subscriber for message type{}: {} already created'\
        .format(message_type, "" if owner_alias is None else "and owner: {}".format(owner_alias))
    _get_flow_aliases_from_registry()[alias] += 1


def remove_flow_number_for_message_type(message_type, owner_alias=None):
    alias = _create_alias_for_data_structures(message_type, owner_alias)
    assert alias in _get_flow_aliases_from_registry(), \
        'Subscriber for message type{}: {} already created'\
        .format(message_type, "" if owner_alias is None else "and owner: {}".format(owner_alias))
    del _get_flow_aliases_from_registry()[alias]


def get_subscriber(message_type, owner_alias=None, protocol=None,
                   action_on_not_found='raise', action_on_found='return'):
    action_on_not_found_options = ['create', 'raise']
    action_on_found_options = ['return', 'recreate']
    assert action_on_not_found in action_on_not_found_options,\
        'Action: {} not allowed, only possible: {}'.format(action_on_not_found, action_on_not_found_options)
    assert action_on_found in action_on_found_options, \
        'Action: {} not allowed, only possible: {}'.format(action_on_found, action_on_found_options)
    alias = _create_alias_for_data_structures(message_type, owner_alias)
    if alias not in _get_subscribers_aliases_from_registry():
        if action_on_not_found == 'raise':
            raise Exception('Subscriber for message: {}{} not created'
                            .format(message_type, "" if owner_alias is None else "and owner: {}".format(owner_alias)))
        elif action_on_not_found == 'create':
            _get_subscribers_aliases_from_registry()[alias] = \
                user_single_message_subscriber(message_type, subscribed_owner_alias=owner_alias, protocol=protocol)
    else:
        if action_on_found == 'return':
            pass
        elif action_on_found == 'recreate':
            print('Checking if found observer is running...')
            _get_subscribers_aliases_from_registry()[alias].wait_until_observer_end()
            print('Removing its subscriber alias and flow alias')
            del _get_subscribers_aliases_from_registry()[alias]
            del _get_flow_aliases_from_registry()[alias]
            print('Creating new subscriber')
            _get_subscribers_aliases_from_registry()[alias] = \
                user_single_message_subscriber(message_type, subscribed_owner_alias=owner_alias, protocol=protocol)
    return _get_subscribers_aliases_from_registry()[alias]


def get_messages_from_subscriber(message_type, owner_alias=None, subscriber_owner_alias=None,
                                 parsed=False, occurrences=None):
    """
    Two aliases need to be provided. If subscriber was used with owner_alias param, subscriber_owner_alias
    must be specified to get proper subscriber.
    After proper subscriber is selected, all messsages can be returned or just messages filtered by owner_alias param

    """
    subscriber = get_subscriber(message_type, owner_alias=subscriber_owner_alias, action_on_not_found='raise')
    if not parsed:
        msgs = subscriber.get_messages_for_owner(owner_alias=owner_alias)
    else:
        msgs = subscriber.get_parsed_messages_for_owner(owner_alias=owner_alias)
    print('Found: {} of type {}{}'
          .format(len(msgs), message_type,
                  " for owner: {}".format(owner_alias) if owner_alias is not None else ""))
    if occurrences is not None:
        assert len(msgs) == int(occurrences), 'Expected: {} messages, got: {}'.format(occurrences, len(msgs))
    return msgs


def get_alias_of_owner_from_unparsed_message(message, action_on_not_found='raise'):
    assert action_on_not_found in ['raise', 'log'], 'Not supported action: {}'.format(action_on_not_found)
    ne_instances = {elem.network_elem_identifier.alias: elem.network_elem_identifier for elem in
                    list(aliases_registry().values())
                    if ((hasattr(elem, 'network_elem_identifier'))
                        and (elem.network_elem_identifier.network_elem_type == message.owner.network_elem_type))
                    }
    for ne_instance_alias in ne_instances:
        if ne_instances[ne_instance_alias] == message.owner:
            return ne_instance_alias
    user_message = 'Found {} instances: {} but not matching identifier: {}'\
        .format(len(ne_instances), pprint.pformat(ne_instances), message.owner)
    if action_on_not_found == 'raise':
        raise Exception(user_message)
    elif action_on_not_found == 'log':
        print(user_message)
        return None


def user_single_message_subscriber_subscribe(message_type, timeout=None, msg_num=None, owner_alias=None, protocol=None):
    """
    owner_alias to be used only when expecting multiple messages for the same owner, e.g. > 99.
    If such condition is met, just catch all messages of given type. Then messages catched for specific owner can be
    retrieved.
    """
    subscriber = get_subscriber(message_type, owner_alias=owner_alias, protocol=protocol,
                                action_on_not_found='create',
                                action_on_found='recreate')
    increment_flow_number_for_message_type(message_type, owner_alias)
    subscriber.subscribe(timeout=timeout, msg_num=msg_num)


def user_single_message_subscriber_register_user_callback(message_type, callback, owner_alias=None):
    subscriber = get_subscriber(message_type, owner_alias=owner_alias, action_on_not_found='create')
    subscriber.register_user_callback(callback=callback)


def user_single_message_subscriber_register_user_verifier(message_type, verifier, owner_alias=None):
    subscriber = get_subscriber(message_type, owner_alias=owner_alias, action_on_not_found='create')
    subscriber.register_user_verifier(verifier=verifier)


class user_single_message_subscriber(MessagesSubscriber):
    ROBOT_LISTENER_API_VERSION = 2
    ROBOT_LIBRARY_SCOPE = "GLOBAL"

    def __init__(self, subscribed_message_type, subscribed_owner_alias=None, protocol=None):
        super(user_single_message_subscriber, self).__init__()
        self.ROBOT_LIBRARY_LISTENER = self
        self.message_type = subscribed_message_type
        self.awaited_owner_alias = subscribed_owner_alias
        self.protocol = protocol
        self.queues_for_messages = {}
        self.queues_for_parsed_messages = {}
        self.timer = None
        self.no_timer = None
        self.awaited_msgs_number = None
        self.subscribed = None
        self._callbacks = [self._save_callback]
        self._verifiers = []
        self._verifiers_raw_names = []
        add_flow_number_for_message_type(self.message_type, self.awaited_owner_alias)
        self.alias_for_structures = _create_alias_for_data_structures(self.message_type, self.awaited_owner_alias)
        self._still_observing = threading.Semaphore(0)

    def is_running(self):
        return self.subscribed

    def wait_until_observer_end(self):
        if self.is_running() is True:
            print('Observer is running, must wait until the end of it')
            self._still_observing.acquire()
        elif self.is_running() is False:
            print('Observer already ended, no waiting')
        else:
            raise Exception('Output of is_running() option: {} not supported'.format(self.is_running()))

    def _end_suite(self, name, attr):
        if _is_dry_run():
            return
        self.stop()

    def register_user_callback(self, callback):
        if not isinstance(callback, types.FunctionType):
            callback_normalized = re.sub(r'\s+', '_', str(callback).lower())
            reg_verifiers = get_registered_verifiers()
            assert callback_normalized in reg_verifiers,\
                'Callback: {} not in registered verifiers. Use @message_verifier decorator'
            callback = reg_verifiers[callback_normalized].__wrapped__
        self._callbacks.append(callback)
        print('Registered callback: {}'.format(len(self._callbacks)))

    def register_user_verifier(self, verifier):
        if not isinstance(verifier, types.FunctionType):
            callback_normalized = re.sub(r'\s+', '_', str(verifier).lower())
            reg_verifiers = get_registered_verifiers()
            if callback_normalized in reg_verifiers:
                verifier = reg_verifiers[callback_normalized].__wrapped__
            else:
                print('Verifier: {} not in registered verifiers. Use @message_verifier decorator.'
                      ' Trying to compile query language validator')
                verifier = message_query_parser().parse(input=verifier)['action_result']
            self._verifiers_raw_names.append(callback_normalized)
        else:
            self._verifiers_raw_names.append(verifier)
        self._verifiers.append(verifier)
        print('Registered verifier: {}'.format(len(self._verifiers)))

    def remove_user_callback(self, callback):
        self._callbacks.remove(callback)

    def cancel_subscription(self):
        print('Canceling subscription of {}{}'
              .format(self.message_type,
                      "" if self.awaited_owner_alias is None else " and owner alias:{}"
                      .format(self.awaited_owner_alias)))
        self._manager.dispatcher.unsubscribe_observer(self.queue_for_messages)
        self.timer = None
        self.no_timer = None
        self.awaited_msgs_number = None
        self.subscribed = False
        self._still_observing.release()

    def stop(self):
        if hasattr(self, 'timer') and self.timer is not None:
            self.timer.cancel()
        self._still_observing.release()
        super(user_single_message_subscriber, self).stop()

    def _save_callback(self, owner_alias, message):

        self.queues_for_messages[_get_flow_aliases_from_registry()[self.alias_for_structures]]\
            .setdefault(str(owner_alias), []).append(message)
        owner_messages = \
            self.queues_for_messages[_get_flow_aliases_from_registry()[self.alias_for_structures]][str(owner_alias)]
        print('Number of saved messages: {} for owner: {}'.format(len(owner_messages), owner_alias))

    def on_new_message(self, message):
        owner_alias = get_alias_of_owner_from_unparsed_message(message, action_on_not_found='log')
        if owner_alias is None:
            print('Droping {} message, alias for owner: {} not created'
                  .format(self.message_type, message.owner))
            return
        if self.awaited_owner_alias is not None and str(self.awaited_owner_alias) != str(owner_alias):
            print('Droping {} message, alias for owner: {} not matching awaited alias: {}'
                  .format(self.message_type, owner_alias, self.awaited_owner_alias))
            return
        message_type = message.message_type
        if self.message_type == message_type:   # log purposes only, logs despite the subscription
            protocol_str = " protocol: {}".format(message.protocol) \
                if hasattr(message, 'protocol') and message.protocol is not None else ""
            print("[SUBSCRIBER] Got message: {} for owner: {}{}".format(message_type, owner_alias, protocol_str))
        if self.protocol is not None and hasattr(message, 'protocol') \
                and str(message.protocol).lower() != str(self.protocol).lower():
            print('[SUBSCRIBER] Dropping message: {} for owner: {} due to different protocol.'
                  ' Expected: {}, got: {}'.format(message_type, owner_alias,
                                                  str(self.protocol).lower(),
                                                  str(message.protocol).lower()))
            return
        if self.no_timer is True or (self.timer is not None and self.timer.is_alive()):
            if message_type == self.message_type:
                curr_time = datetime.datetime.now().time()
                if len(self._verifiers):
                    parsed_message = message.parse()
                    results = [ver(parsed_message) for ver in self._verifiers]
                else:
                    results = []
                if len(results) == 0 or all(results) is True:
                    print('[{}] Accepting {} message, putting into storage for flow {}, owner {}'
                          .format(curr_time, self.message_type,
                                  _get_flow_aliases_from_registry()[self.alias_for_structures],
                                  owner_alias))
                    for callback in self._callbacks:
                        callback(owner_alias, message)
                    self.await_for_msg_num()
                else:
                    print('Dropping {} message due to '
                          'not being accepted: {} by all verifiers: {}. Callbacks not being executed!'
                          .format(message, results, self._verifiers_raw_names))
            else:
                pass
                # print('Droping {} message, subscription only for {}'.format(message_type, self.message_type))
        else:
            print('Droping {} message, no subscription'.format(self.message_type))

    def await_for_msg_num(self):
        if self.awaited_msgs_number is not None and self.awaited_msgs_number > 0:
            self.awaited_msgs_number -= 1
            print('Current amount of awaited msgs: {}'.format(self.awaited_msgs_number))
            if self.awaited_msgs_number == 0:
                print('All awaited messages caught, canceling observer earlier')
                self.awaited_msgs_number = None
                if self.timer is not None:
                    self.timer.cancel()
                self.cancel_subscription()

    def _subscribe(self, owner=None):
        if self.subscribed:
            raise Exception('Can subscribe only once per observer, create another observer')
        self._manager.dispatcher.subscribe_observer(self.queue_for_messages,
                                                    message_type=self.message_type, owner=owner)
        self.subscribed = True

    def subscribe(self, timeout=None, msg_num=None):
        assert _get_flow_aliases_from_registry()[self.alias_for_structures] not in \
               list(self.queues_for_messages.keys()),\
            'FLOW number {} already created'.format(_get_flow_aliases_from_registry()[self.alias_for_structures])
        self.queues_for_messages[_get_flow_aliases_from_registry()[self.alias_for_structures]] = {}
        self.queues_for_parsed_messages[_get_flow_aliases_from_registry()[self.alias_for_structures]] = {}
        self._still_observing = threading.Semaphore(0)
        self._subscribe()
        self.awaited_msgs_number = int(msg_num) if msg_num is not None else None
        if timeout:
            self.timer = threading.Timer(int(timeout), self.cancel_subscription)
            self.timer.start()
        else:
            self.no_timer = True
        print('Subscribed successfully for: {}'.format(self.message_type))

    # def get_from_indefinite_observer_messages_for_owner(self, owner_alias=None):
    #     flow_number = None
    #
    # def get_from_indefinite_observer_parsed_messages_for_owner(self, owner_alias=None):
    #     flow_number = None

    def get_messages_for_owner(self, owner_alias=None, flow_number=None):
        flow_number = self.retrieve_flow_number(flow_number)
        if owner_alias is not None:
            assert self.is_any_message_for_owner(owner_alias, flow_number), \
                'Owner {} not found in possible owners {}'\
                .format(owner_alias, list(self.queues_for_messages[flow_number].keys()))
            return self.queues_for_messages[flow_number][str(owner_alias)]
        else:
            assert self._is_any_message_in_flow(flow_number), 'No messages found in flow'
            messages = []
            for alias in self.queues_for_messages[flow_number]:
                messages.extend(self.queues_for_messages[flow_number][str(alias)])
            return messages

    def get_parsed_messages_for_owner(self, owner_alias=None, flow_number=None):
        flow_number = self.retrieve_flow_number(flow_number)
        if owner_alias is not None:
            if flow_number not in self.queues_for_parsed_messages \
               or str(owner_alias) not in self.queues_for_parsed_messages[flow_number]:
                owner_messages = self.get_messages_for_owner(owner_alias, flow_number)
                parsed_messages = [message.parse() for message in owner_messages]
                self.queues_for_parsed_messages[flow_number][str(owner_alias)] = parsed_messages
            return self.queues_for_parsed_messages[flow_number][str(owner_alias)]
        else:
            if flow_number not in self.queues_for_parsed_messages \
               or str(owner_alias) not in self.queues_for_parsed_messages[flow_number]:
                owner_messages = self.get_messages_for_owner(owner_alias, flow_number)
                parsed_messages = [message.parse() for message in owner_messages]
                self.queues_for_parsed_messages[flow_number][str(owner_alias)] = parsed_messages
            return self.queues_for_parsed_messages[flow_number][str(owner_alias)]

    def is_any_message_for_owner(self, owner_alias, flow_number=None, wait_for_running_flow=True):
        print('Received request for Flow: {}'.format(flow_number))
        flow_number = self.retrieve_flow_number(flow_number)
        if self._is_any_message_in_flow(flow_number=flow_number, wait_for_running_flow=wait_for_running_flow):
            if str(owner_alias) in self.queues_for_messages[flow_number]:
                return True
        return False

    def _is_any_message_in_flow(self, flow_number=None, wait_for_running_flow=True):
        print('Received request for Flow: {}'.format(flow_number))
        flow_number = self.retrieve_flow_number(flow_number)
        if self.is_request_for_current_running_flow(flow_number):
            if wait_for_running_flow:
                print('Waiting for end of observation period')
                self._still_observing.acquire()
            else:
                print('Flow is running, but no waiting')
        else:
            print('Getting to messages from history, not waiting')

        if len(self.queues_for_messages[flow_number]):
            return True
        else:
            return False

    def retrieve_flow_number(self, flow_number):
        if flow_number is None:
            if _get_flow_aliases_from_registry()[self.alias_for_structures] in list(self.queues_for_messages.keys()):
                flow_number = _get_flow_aliases_from_registry()[self.alias_for_structures]
            else:
                flow_number = _get_flow_aliases_from_registry()[self.alias_for_structures] - 1
        return flow_number

    def is_request_for_current_running_flow(self, flow_number):
        return True if self.is_flow_number_current_flow(flow_number) and self.is_any_flow_running() else False

    def is_flow_number_current_flow(self, flow_number):
        return True if int(_get_flow_aliases_from_registry()[self.alias_for_structures]) == int(flow_number) else False

    def is_any_flow_running(self):
        return True if self.timer is not None and self.timer.is_alive() else False
